/// Make the Misere: one mode per set of Disciplines used.
macro_rules! misere {
    ($($e:expr),*) => {
        anarch_bleed(
            LOCKED_COMBAT_TARGET,
            &[
                Effect::DeclareAction(ActionKind::Card),
                Effect::EnterCombatWithTarget,
                $($e),*
            ],
        )
    };
}

